package io.github.iachimoe.tarballfs;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNotNull;
import static org.junit.jupiter.api.Assertions.assertNull;
import static org.junit.jupiter.api.Assertions.assertSame;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.net.URI;
import java.nio.file.FileSystems;
import java.nio.file.Path;
import java.nio.file.spi.FileSystemProvider;
import org.junit.jupiter.api.Test;

class AbstractCompressorArchiveFileSystemMutaGate1Test {

  private static final class TestFs extends AbstractCompressorArchiveFileSystem {
    TestFs(
        FileSystemProvider provider,
        URI uri,
        Path hostArchivePath,
        String fileStoreType,
        String virtualEntryName,
        Path uncompressedTempFile) {
      super(provider, uri, hostArchivePath, fileStoreType, virtualEntryName, uncompressedTempFile);
    }

    @Override
    protected void deregister(URI uri) {
    }

    @Override
    protected SingleEntryArchiveFormat pathFormat() {
      return SingleEntryArchiveFormat.GZIP;
    }
  }

  @Test
  void constructorStoresArgumentsAndRejectsNulls() {
    FileSystemProvider provider = FileSystems.getDefault().provider();
    URI uri = URI.create("gzip:file:///tmp/a.gz");
    Path archive = Path.of("a.gz");
    Path temp = Path.of("a.tmp");

    TestFs fs = new TestFs(provider, uri, archive, "gzip", "a", temp);
    assertSame(provider, fs.provider());
    assertSame(archive, fs.hostArchivePath());
    assertEquals("a", fs.virtualEntryName());
    assertSame(temp, fs.uncompressedTempFile());
    assertNotNull(fs.compressorFileStore());
    assertTrue(fs.isOpen());
    assertTrue(fs.isReadOnly());

    NullPointerException e =
        assertThrows(NullPointerException.class, () -> new TestFs(null, uri, archive, "gzip", "a", temp));
    assertEquals("provider", e.getMessage());

    e = assertThrows(NullPointerException.class, () -> new TestFs(provider, null, archive, "gzip", "a", temp));
    assertEquals("uri", e.getMessage());

    e = assertThrows(NullPointerException.class, () -> new TestFs(provider, uri, null, "gzip", "a", temp));
    assertEquals("hostArchivePath", e.getMessage());

    e = assertThrows(NullPointerException.class, () -> new TestFs(provider, uri, archive, null, "a", temp));
    assertNull(e.getMessage());

    e = assertThrows(NullPointerException.class, () -> new TestFs(provider, uri, archive, "gzip", null, temp));
    assertEquals("virtualEntryName", e.getMessage());

    e = assertThrows(NullPointerException.class, () -> new TestFs(provider, uri, archive, "gzip", "a", null));
    assertEquals("uncompressedTempFile", e.getMessage());
  }
}

package io.github.iachimoe.tarballfs;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.io.IOException;
import java.net.URI;
import java.nio.file.FileSystems;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.spi.FileSystemProvider;
import java.util.ArrayList;
import java.util.List;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

class AbstractCompressorArchiveFileSystemMutaGate2Test {

  private static final class TestFileSystem extends AbstractCompressorArchiveFileSystem {
    final List<URI> deregistered = new ArrayList<>();

    TestFileSystem(FileSystemProvider provider, URI uri, Path archive, Path tempFile) {
      super(provider, uri, archive, "gzip", "entry.txt", tempFile);
    }

    @Override
    protected void deregister(URI uri) {
      deregistered.add(uri);
    }

    @Override
    protected SingleEntryArchiveFormat pathFormat() {
      return SingleEntryArchiveFormat.GZIP;
    }
  }

  @Test
  void closeStillDeregistersWhenDeleteFailsAndSecondCloseIsNoOp(@TempDir Path dir) throws IOException {
    Path archive = dir.resolve("a.gz");
    Files.writeString(archive, "x");

    // A non-empty directory cannot be deleted by Files.deleteIfExists
    Path tempDirAsFile = dir.resolve("tmpdir");
    Files.createDirectory(tempDirAsFile);
    Files.writeString(tempDirAsFile.resolve("child"), "data");

    URI uri = URI.create("gzip:" + archive.toUri());
    TestFileSystem fs =
        new TestFileSystem(FileSystems.getDefault().provider(), uri, archive, tempDirAsFile);

    assertTrue(fs.isOpen());

    assertThrows(IOException.class, fs::close);

    assertFalse(fs.isOpen());
    assertEquals(List.of(uri), fs.deregistered);
    assertTrue(Files.exists(tempDirAsFile.resolve("child")));

    // Second close returns immediately without throwing or deregistering again
    fs.close();
    assertEquals(1, fs.deregistered.size());
    assertFalse(fs.isOpen());
  }
}

package io.github.iachimoe.tarballfs;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertSame;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.io.IOException;
import java.net.URI;
import java.nio.file.ClosedFileSystemException;
import java.nio.file.FileSystems;
import java.nio.file.Path;
import java.util.UUID;
import org.junit.jupiter.api.Test;

class AbstractCompressorArchiveFileSystemMutaGate3Test {

  private static final class TestFileSystem extends AbstractCompressorArchiveFileSystem {
    TestFileSystem(URI uri, Path archive, Path temp) {
      super(FileSystems.getDefault().provider(), uri, archive, "test", "entry", temp);
    }

    @Override
    protected void deregister(URI uri) {
      // nothing to deregister
    }

    @Override
    protected SingleEntryArchiveFormat pathFormat() {
      return SingleEntryArchiveFormat.GZIP;
    }
  }

  @Test
  void getPathBuildsPathsBoundToFileSystemAndFailsAfterClose() throws IOException {
    Path tmpDir = Path.of(System.getProperty("java.io.tmpdir"));
    Path archive = tmpDir.resolve("archive-" + UUID.randomUUID() + ".gz");
    Path temp = tmpDir.resolve("uncompressed-" + UUID.randomUUID());
    TestFileSystem fs = new TestFileSystem(URI.create("test:///" + UUID.randomUUID()), archive, temp);

    Path absolute = fs.getPath("/foo");
    Path relative = fs.getPath("foo");

    SingleEntryArchivePath absPath = assertInstanceOf(absolute);
    SingleEntryArchivePath relPath = assertInstanceOf(relative);

    assertSame(fs, absPath.getFileSystem());
    assertSame(fs, relPath.getFileSystem());
    assertEquals(SingleEntryArchiveFormat.GZIP, absPath.format());
    assertEquals(SingleEntryArchiveFormat.GZIP, relPath.format());
    assertTrue(absPath.isAbsolute());
    assertFalse(relPath.isAbsolute());
    assertEquals(relPath.entryName(), absPath.entryName());

    assertEquals(fs.getPath("a/b"), fs.getPath("a", "b"));

    fs.close();
    assertThrows(ClosedFileSystemException.class, () -> fs.getPath("foo"));
    assertThrows(ClosedFileSystemException.class, () -> fs.getPath("/"));
  }

  private static SingleEntryArchivePath assertInstanceOf(Path path) {
    assertTrue(path instanceof SingleEntryArchivePath);
    return (SingleEntryArchivePath) path;
  }
}

